package mz.co.aprendaacodar.user.service;
import mz.co.aprendaacodar.common.enums.Enums.*;import mz.co.aprendaacodar.common.exception.*;import mz.co.aprendaacodar.security.RefreshTokenRepository;import mz.co.aprendaacodar.user.dto.TeacherDtos.*;import mz.co.aprendaacodar.user.entity.*;import mz.co.aprendaacodar.user.repository.*;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Service public class TeacherService {
 private final UserRepository users;private final TeacherProfileRepository profiles;private final PasswordEncoder encoder;private final RefreshTokenRepository tokens;
 public TeacherService(UserRepository u,TeacherProfileRepository p,PasswordEncoder e,RefreshTokenRepository t){users=u;profiles=p;encoder=e;tokens=t;}
 @Transactional public TeacherResponse create(CreateTeacherRequest r){if(users.existsByEmailIgnoreCase(r.email()))throw new BusinessException("Este e-mail já está registado.");User u=users.save(new User(r.firstName(),r.lastName(),r.email(),r.phoneNumber(),encoder.encode(r.password()),UserRole.TEACHER));TeacherProfile p=profiles.save(new TeacherProfile(u,r.biography(),r.specialization(),r.professionalTitle()));return map(p);}
 @Transactional(readOnly=true) public List<TeacherResponse> list(){return profiles.findAll().stream().map(this::map).toList();}@Transactional(readOnly=true) public TeacherResponse get(UUID id){return map(profiles.findByUserId(id).orElseThrow(()->new ResourceNotFoundException("Professor não encontrado.")));}
 @Transactional public TeacherResponse update(UUID id,UpdateTeacherRequest r){TeacherProfile p=profiles.findByUserId(id).orElseThrow(()->new ResourceNotFoundException("Professor não encontrado."));if(!p.getUser().getEmail().equalsIgnoreCase(r.email())&&users.existsByEmailIgnoreCase(r.email()))throw new BusinessException("Este e-mail já está registado.");User u=p.getUser();u.updateProfile(r.firstName(),r.lastName(),r.phoneNumber());u.setEmail(r.email());p.update(r.biography(),r.specialization(),r.professionalTitle());return map(p);}
 @Transactional public void deactivate(UUID id){TeacherProfile p=profiles.findByUserId(id).orElseThrow(()->new ResourceNotFoundException("Professor não encontrado."));p.getUser().setStatus(UserStatus.INACTIVE);tokens.revokeByUserId(id);}
 private TeacherResponse map(TeacherProfile p){User u=p.getUser();return new TeacherResponse(u.getId(),u.getFirstName(),u.getLastName(),u.getEmail(),u.getPhoneNumber(),p.getBiography(),p.getSpecialization(),p.getProfessionalTitle(),u.getStatus().name());}
}
